CREATE TABLE BURIALS (
  BURIAL_ID INTEGER NOT NULL PRIMARY KEY,
  SITE_ID INTEGER NOT NULL,
  REF VARCHAR(20) NOT NULL,
  DATING VARCHAR(10) NOT NULL,
  CONTAINS_AMULET BOOLEAN NOT NULL,
  DISTURBED BOOLEAN NOT NULL,
  SUPER VARCHAR(20),
  SUB VARCHAR(20),
  ENCLOSURE BOOLEAN NOT NULL,
  CHAPEL BOOLEAN NOT NULL,
  STAIRS BOOLEAN NOT NULL,
  CHAMBERS INTEGER NOT NULL,
  DECORATED BOOLEAN NOT NULL,
  BENCH BOOLEAN NOT NULL,
  SLOPE BOOLEAN NOT NULL,
  BRICKS BOOLEAN NOT NULL,
  REUSED BOOLEAN NOT NULL,
  NICHES BOOLEAN NOT NULL,
  BED_HOLES BOOLEAN NOT NULL,
  ROOF BOOLEAN NOT NULL,
  TRENCHES BOOLEAN NOT NULL,
  SHAFT BOOLEAN NOT NULL,
  OFF_PLACE BOOLEAN NOT NULL,
  NOT_EXC BOOLEAN NOT NULL,
  SOCIAL_GROUP VARCHAR(45),
  TEMP VARCHAR(45),
  OWNER VARCHAR(20),
  TEMP_EARLY VARCHAR(45),
  TEMP_LATE VARCHAR(45),
  CONSTRAINT FK_BURIALS_SITE FOREIGN KEY (SITE_ID) REFERENCES SITES ON DELETE RESTRICT
);
